import { WORLD_WORKSHOP_API_BASE, WORLD_WORKSHOP_AUTH_TOKEN_KEY } from './worldWorkshop';

export interface CloudAccountUser {
  id: number;
  discord_id: string;
  username: string;
  display_name: string;
  avatar: string;
  role: string;
  is_admin: boolean;
  created_at?: string;
}

export interface CloudLoginResponse {
  token: string;
  user: CloudAccountUser;
}

function getHostStorage(): Storage | null {
  if (typeof window === 'undefined') return null;
  try {
    return window.parent?.localStorage || window.localStorage;
  } catch {
    return null;
  }
}

export function getCloudAuthToken(): string | null {
  try {
    return getHostStorage()?.getItem(WORLD_WORKSHOP_AUTH_TOKEN_KEY) || null;
  } catch {
    return null;
  }
}

export function setCloudAuthToken(token: string): void {
  getHostStorage()?.setItem(WORLD_WORKSHOP_AUTH_TOKEN_KEY, token);
}

export function clearCloudAuthToken(): void {
  getHostStorage()?.removeItem(WORLD_WORKSHOP_AUTH_TOKEN_KEY);
}

export function getCloudRegisterUrl(endpointBase = WORLD_WORKSHOP_API_BASE): string {
  return `${endpointBase}/auth/discord`;
}

async function cloudAuthRequest<T>(
  path: string,
  opts: RequestInit = {},
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<T> {
  const token = getCloudAuthToken();
  const headers: Record<string, string> = {
    ...((opts.headers as Record<string, string> | undefined) || {}),
  };

  if (token) headers.Authorization = `Bearer ${token}`;
  if (!(opts.body instanceof FormData)) headers['Content-Type'] = 'application/json';

  const response = await fetch(`${endpointBase}${path}`, {
    ...opts,
    headers,
  });

  if (!response.ok) {
    const data = await response.json().catch(() => ({ error: `HTTP ${response.status}` }));
    throw new Error(data.error || `云端账号请求失败：${response.status}`);
  }

  return response.json() as Promise<T>;
}

export async function loginCloudAccountWithPassword(
  username: string,
  password: string,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<CloudLoginResponse> {
  const result = await cloudAuthRequest<CloudLoginResponse>(
    '/auth/login',
    {
      method: 'POST',
      body: JSON.stringify({ username, password }),
    },
    endpointBase,
  );
  setCloudAuthToken(result.token);
  return result;
}

export async function fetchCloudAccountMe(endpointBase = WORLD_WORKSHOP_API_BASE): Promise<CloudAccountUser> {
  return cloudAuthRequest<CloudAccountUser>('/auth/me', {}, endpointBase);
}

export async function logoutCloudAccountSession(endpointBase = WORLD_WORKSHOP_API_BASE): Promise<void> {
  try {
    if (getCloudAuthToken()) {
      await cloudAuthRequest('/auth/logout', { method: 'POST' }, endpointBase);
    }
  } finally {
    clearCloudAuthToken();
  }
}
